const item = $input.first();
const secret = $env.SHOP_OWNER_WEBHOOK_SECRET;
const headers = item.json.headers || {};
const body = (item.json.body && typeof item.json.body === 'object') ? item.json.body : item.json;
const headerSecret = String(headers['x-shop-webhook-secret'] || headers['X-Shop-Webhook-Secret'] || '');
const bodySecret = String(body.webhookSecret || item.json.webhookSecret || '');
const authorized = !!secret && (headerSecret === secret || bodySecret === secret);

const orderId = body.orderId ? Number(body.orderId) : null;
let hours = body.hours === undefined || body.hours === '' ? 72 : Number(body.hours);
if (!Number.isFinite(hours) || hours < 0) hours = 72;
let limit = body.limit ? Number(body.limit) : 15;
if (!Number.isInteger(limit) || limit <= 0) limit = 15;
if (limit > 50) limit = 50;
const statusesRaw = String(body.statuses || 'pending,confirmed,paid');

let error = '';
let httpStatus = 200;
if (!authorized) { error = 'Unauthorized webhook'; httpStatus = 401; }
else if (orderId !== null && (!Number.isInteger(orderId) || orderId <= 0)) { error = 'orderId must be a positive integer'; httpStatus = 400; }

return [{ json: {
  ok: !error, error, httpStatus, orderId, hours, limit, statusesRaw,
  apiBase: $env.API_BASE_URL || 'http://backend:8080/api',
  siteBase: $env.CONTENT_ADMIN_BASE_URL || 'https://lucaloupe.com'
} }];

const parsed = $('Parse Payload').item.json;
const login = $input.first().json;
const token = login.data?.accessToken || login.accessToken || login.data?.AccessToken;
if (!token) return [{ json: { ok: false, httpStatus: 502, error: login.error || 'Login failed: no access token' } }];
return [{ json: { ...parsed, accessToken: token } }];

const ctx = $input.first().json;
const headers = { Authorization: `Bearer ${ctx.accessToken}` };
const api = ctx.apiBase;
const STATUS_FA = { 0: 'ثبت اولیه', 1: 'تایید شده', 2: 'پرداخت شده', 3: 'ارسال شده', 4: 'تحویل داده شده', 5: 'لغو شده' };
const NAME_TO_NUM = { pending: 0, confirmed: 1, paid: 2, shipped: 3, delivered: 4, cancelled: 5 };
const statusNum = (s) => {
  if (typeof s === 'number' && Number.isFinite(s)) return s;
  const k = String(s ?? '').trim().toLowerCase();
  if (k in NAME_TO_NUM) return NAME_TO_NUM[k];
  const n = Number(k);
  return Number.isFinite(n) ? n : null;
};
const statusFa = (s) => STATUS_FA[statusNum(s)] || String(s ?? '');
const money = (n) => Number(n || 0).toLocaleString('fa-IR');
const whenFa = (iso) => {
  try { return new Date(iso).toLocaleString('fa-IR', { timeZone: 'Asia/Tehran' }); }
  catch { return String(iso || ''); }
};
const unwrap = (res) => {
  if (Array.isArray(res)) return res;
  if (Array.isArray(res?.data)) return res.data;
  if (Array.isArray(res?.data?.records)) return res.data.records;
  return res?.data ?? res;
};
const http = async (method, url) => {
  const res = await this.helpers.httpRequest({
    method, url, headers, json: true, ignoreHttpStatusErrors: true, returnFullResponse: true
  });
  const status = res.statusCode || res.status || 200;
  const payload = res.body !== undefined ? res.body : res;
  if (status >= 400) {
    const err = payload?.error || payload?.title || payload?.message || `HTTP ${status}`;
    const e = new Error(String(err));
    e.statusCode = status;
    throw e;
  }
  return payload;
};
const itemLine = (it) => {
  const name = it?.product?.name || it?.product?.Name || 'کالا';
  const qty = it?.quantity ?? it?.Quantity ?? 1;
  return `${name} ×${qty}`;
};

try {
  if (ctx.orderId) {
    const raw = await http('GET', `${api}/Orders/${ctx.orderId}`);
    if (raw?.isSuccess === false) {
      return [{ json: { ok: false, httpStatus: 404, error: raw.error || 'Order not found' } }];
    }
    const o = unwrap(raw);
    const items = (o.items || o.Items || []).map(itemLine);
    const addr = o.shippingAddress || o.ShippingAddress || {};
    const textFa = [
      `سفارش #${o.id}`,
      `وضعیت: ${statusFa(o.status)}`,
      `تاریخ: ${whenFa(o.orderDate)}`,
      `مبلغ: ${money(o.totalPrice)}`,
      o.paymentMethod?.title ? `پرداخت: ${o.paymentMethod.title}` : null,
      o.shippingMethod?.title ? `ارسال: ${o.shippingMethod.title}` : null,
      items.length ? `اقلام:\n- ${items.join('\n- ')}` : 'اقلام: —',
      addr.fullAddress ? `آدرس: ${[addr.name, addr.state, addr.city, addr.fullAddress].filter(Boolean).join('، ')}` : null
    ].filter(Boolean).join('\n');
    return [{ json: { ok: true, httpStatus: 200, mode: 'detail', orderId: o.id, status: statusFa(o.status), totalPrice: o.totalPrice, textFa } }];
  }

  const wanted = String(ctx.statusesRaw || '')
    .split(/[+,]/)
    .map(s => statusNum(s.trim()))
    .filter(n => n !== null);
  const wantedSet = new Set(wanted.length ? wanted : [0, 1, 2]);
  const raw = await http('GET', `${api}/Orders/open`);
  const list = unwrap(raw) || [];
  const all = Array.isArray(list) ? list : [];
  const cutoff = ctx.hours > 0 ? Date.now() - ctx.hours * 3600 * 1000 : 0;
  const filtered = all
    .filter(o => wantedSet.has(statusNum(o.status)))
    .filter(o => !cutoff || new Date(o.orderDate).getTime() >= cutoff)
    .sort((a, b) => new Date(b.orderDate) - new Date(a.orderDate));
  const sliced = filtered.slice(0, ctx.limit);
  const counts = {};
  for (const o of filtered) {
    const k = statusFa(o.status);
    counts[k] = (counts[k] || 0) + 1;
  }
  const lines = sliced.map(o => {
    const items = (o.items || []).map(itemLine);
    return [`#${o.id} ${statusFa(o.status)} — ${money(o.totalPrice)} — ${whenFa(o.orderDate)}`, items.length ? `  - ${items.join('\n  - ')}` : '  - (بدون قلم)'].join('\n');
  });
  const header = ctx.hours > 0
    ? `سفارش‌های باز (${ctx.hours} ساعت اخیر)`
    : 'سفارش‌های باز';
  const textFa = filtered.length === 0
    ? `${header}\nموردی نیست.`
    : [header, `تعداد: ${filtered.length}`, Object.entries(counts).map(([k, v]) => `${k}: ${v}`).join('، '), '', ...lines].join('\n');
  return [{ json: {
    ok: true, httpStatus: 200, mode: 'list', hours: ctx.hours, total: filtered.length, counts,
    orders: sliced.map(o => ({ id: o.id, status: statusFa(o.status), totalPrice: o.totalPrice, orderDate: o.orderDate, items: (o.items || []).map(itemLine) })),
    textFa
  } }];
} catch (e) {
  return [{ json: { ok: false, httpStatus: e.statusCode || 502, error: e.message || String(e) } }];
}
